<?php

namespace App\Models;

use App\Models\Concerns\BelongsToHousehold;
use App\Support\Week;
use Carbon\CarbonImmutable;
use Illuminate\Database\Eloquent\Attributes\Fillable;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Relations\HasMany;
use Illuminate\Support\Carbon;

/**
 * Shopping list of a purchase period (RN-36), kept in the database with its manual lines,
 * edited quantities and purchases. Lists generated by closing a weekly menu before 2026-10-21
 * have a menu and no period: they are kept as read-only history. Never touches stock (RN-25).
 *
 * @property int $id
 * @property int|null $menu_id
 * @property int $household_id
 * @property CarbonImmutable|null $period_start
 * @property CarbonImmutable|null $period_end
 * @property int|null $rolling_days
 * @property Carbon $generated_at
 * @property Carbon|null $regenerated_at
 * @property-read Menu|null $menu
 */
#[Fillable(['menu_id', 'household_id', 'period_start', 'period_end', 'rolling_days', 'generated_at', 'regenerated_at'])]
class ShoppingList extends Model
{
    use BelongsToHousehold;

    /**
     * @return BelongsTo<Menu, $this>
     */
    public function menu(): BelongsTo
    {
        return $this->belongsTo(Menu::class);
    }

    /**
     * @return HasMany<ShoppingListItem, $this>
     */
    public function items(): HasMany
    {
        return $this->hasMany(ShoppingListItem::class);
    }

    /**
     * @return HasMany<Reception, $this>
     */
    public function receptions(): HasMany
    {
        return $this->hasMany(Reception::class);
    }

    /**
     * First and last day the list covers: its period, or the week of its menu for old lists.
     *
     * @return array{0: CarbonImmutable, 1: CarbonImmutable}
     */
    public function range(): array
    {
        if ($this->period_start !== null && $this->period_end !== null) {
            return [$this->period_start, $this->period_end];
        }

        $start = CarbonImmutable::parse($this->menu?->week_start->format('Y-m-d') ?? $this->generated_at->format('Y-m-d'));

        return [$start, $start->addDays(6)];
    }

    /**
     * Only period lists that have not ended are edited and received; the rest is history.
     */
    public function isActive(): bool
    {
        // A quick list («Próximos N días») moves with today: it is never history.
        if ($this->rolling_days !== null) {
            return true;
        }

        return $this->period_end !== null
            && $this->period_end->format('Y-m-d') >= CarbonImmutable::now(Week::timezone())->format('Y-m-d');
    }

    public function label(): string
    {
        [$start, $end] = $this->range();
        $format = fn (CarbonImmutable $date) => $date->translatedFormat('j \\d\\e F \\d\\e Y');

        return match (true) {
            $this->period_start === null => 'Lista semanal del '.$format($start).' al '.$format($end),
            $this->rolling_days !== null => "Próximos {$this->rolling_days} días: del {$format($start)} al {$format($end)}",
            default => 'Del '.$format($start).' al '.$format($end),
        };
    }

    /**
     * @return array<string, string>
     */
    protected function casts(): array
    {
        return [
            'period_start' => 'immutable_date',
            'period_end' => 'immutable_date',
            'rolling_days' => 'integer',
            'generated_at' => 'datetime',
            'regenerated_at' => 'datetime',
        ];
    }
}
